-- Individually checked November 24, 2026 Pacific. Data-only editorial batch.
begin;
do $curate$ declare r jsonb; bid uuid; applied jsonb; begin
for r in select value from jsonb_array_elements('[{"name": "Ron''s Pool and Spa Service", "city": "Service area only", "phone": "(209) 603-0694", "website": "https://www.ronspoolandspa.com/", "source_url": "https://www.ronspoolandspa.com/services", "tags": ["pool cleaning", "pool maintenance", "pool repair", "spa maintenance"], "description": "Advertises recurring pool cleaning, spa maintenance, filter cleaning and pool equipment repairs. Its official service list names Mountain House, Tracy, Lathrop and Manteca. Call to confirm your address, pool or spa needs, access arrangements, service scope, quote and dates. No public visitor office or current appointment availability established.", "note": "First-party services page freshly checked November 24, 2026 (HTTP200): identity, public phone, advertised maintenance/repair services and individually named service cities. No owner contact, credential/insurance validation, water-safety guarantee, workmanship, ratings, pricing or holiday availability confirmed. No portfolio photos reused.", "areas": ["Mountain House", "Tracy", "Lathrop", "Manteca"]}, {"name": "Smart Repair", "city": "Service area only", "phone": "(510) 283-8087", "website": "https://smart-repair.us/", "source_url": "https://smart-repair.us/service-areas/", "tags": ["appliance repair", "appliance installation"], "description": "Advertises home appliance repair and installation; its service-area page individually names Mountain House, Tracy, Lathrop and Manteca. Contact the business to confirm your appliance, brand, model, address eligibility, diagnostic charges, full quote and appointment. Online intake is a request requiring provider confirmation. No local walk-in shop or Thanksgiving availability established.", "note": "First-party homepage, service-area and appliance booking pages checked November 24, 2026; homepage/service-area fresh HTTP200. Identity, public phone, appliance services and four named cities checked. Advertised license, brand affiliations, insurance, workmanship and appointment availability not independently verified. No fixed diagnostic-price promise, holiday hours, submitted booking, reviews or photos adopted.", "areas": ["Mountain House", "Tracy", "Lathrop", "Manteca"]}]'::jsonb) loop
if exists(select 1 from public.businesses where lower(rtrim(coalesce(website,''),'/'))=lower(rtrim(r->>'website','/')) or right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),10)=right(regexp_replace(r->>'phone','[^0-9]','','g'),10) or lower(name)=lower(r->>'name')) then raise exception 'Duplicate candidate: %',r->>'name';end if;
insert into public.businesses(name,category,city,phone,website,description,status,verified,claimed,rating,review_count,needs_review,source,source_url,verification_source,verified_at)values(r->>'name','Home Services',r->>'city',r->>'phone',r->>'website',r->>'description','approved',true,false,null,0,false,'editorial_first_party',r->>'source_url','first_party_website_desk_check',now())returning id into bid;
insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note)values(bid,r->>'source_url',array['identity','public phone','website','advertised services','explicit service cities','scope and limitations'],array(select jsonb_array_elements_text(r->'areas')),array(select jsonb_array_elements_text(r->'tags')),r->>'note');
select to_jsonb(b) into applied from public.businesses b where id=bid;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference)values(bid,'{}'::jsonb,applied||jsonb_build_object('service_areas',r->'areas','service_tags',r->'tags','scope_note',r->>'note'),'CORE-01 individually checked pool/appliance service expansion; website information only',r->>'source_url');
end loop;end $curate$;
do $correct$ declare bid uuid:='a598f456-4fe7-49b6-9f45-187ba1e33ccf'; old_b jsonb; old_c jsonb; new_c jsonb; begin
select to_jsonb(b) into old_b from businesses b where id=bid and name='Mountain Cleaners' and website='https://mountain-cleaners.com/' and status='approved' and verified and not claimed for update;
select to_jsonb(c) into old_c from listing_checks c where business_id=bid and service_areas=array['Mountain House'] and service_tags=array['trash bin cleaning','solar panel cleaning'] for update;
if old_b is null or old_c is null then raise exception 'Mountain Cleaners evidence changed; review required';end if;
update listing_checks set service_tags=array['trash can cleaning','trash bin cleaning','solar panel cleaning'],checked_at=now(),checked_fields=array['identity','public phone','website','advertised services','explicit service city','canonical service discovery tag'],scope_note='Fresh first-party homepage HTTP200 November 24, 2026: identity, public2093210006, Mountain House coverage, trash-bin and solar-panel cleaning. Added canonical trash can cleaning tag so the existing checked service appears in the new shortlist; original listing approval date preserved. No indoor house cleaning, Tracy/Lathrop/Manteca coverage, bird exclusion, owner availability, credentials, insurance, sanitation/solar-performance or quality confirmed. No photos reused or contact sent.' where business_id=bid;
select to_jsonb(c) into new_c from listing_checks c where business_id=bid;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference)values(bid,old_b||jsonb_build_object('listing_check',old_c),old_b||jsonb_build_object('listing_check',new_c),'Correct existing checked trash-bin service discovery; no new business, coverage expansion or approval-date change','https://mountain-cleaners.com/');
end $correct$;
commit;
